import PulsoLinkCore

/**
 * Near 户外交友门面（对应 Android `OutdoorSocialService`、WEB `hooks/outdoorSocial.ts`）：
 * 读走 [OutdoorSocialQueryStore]；写成功后一次 [OutdoorSocialEventBus.invalidate]。
 */
struct OutdoorSocialService: Sendable {
    let repository: OutdoorSocialRepository
    let query: OutdoorSocialQueryStore
    let eventBus: OutdoorSocialEventBus
    let exploreQuery: ExploreQueryStore

    static let rosterPageSize = OutdoorSocialQueryStore.rosterPageSize

    /** 我主持的活动的收款清单，分页；这个运动的任何写操作都会让它重拉。 */
    @MainActor
    func pageHostedChecklists(isAllSettled: Bool) -> PagedList<HostedChecklistRowUi, Int> {
        let repository = repository
        return .offset(invalidates: { eventBus.signals { _ in true } }) { offset, limit in
            let page = try await repository.listHostedPaymentChecklists(
                OutdoorSocialListHostedPaymentChecklistsRequest(offset: offset, limit: limit, isAllSettled: isAllSettled)
            )
            return ListWithTotal(items: page.items.map(HostedChecklistRowUi.init), total: page.total)
        }
    }

    /** 我自己欠的收款行，分页。 */
    @MainActor
    func pageMyPaymentItems(paid: Bool) -> PagedList<MyChecklistItemRowUi, Int> {
        let repository = repository
        return .offset(invalidates: { eventBus.signals { _ in true } }) { offset, limit in
            let page = try await repository.listMyPaymentChecklistItems(
                OutdoorSocialListMyPaymentChecklistItemsRequest(offset: offset, limit: limit, paid: paid)
            )
            return ListWithTotal(items: page.items.map(MyChecklistItemRowUi.init), total: page.total)
        }
    }

    func prefetchDetail(activityId: String) {
        query.prefetchDetail(activityId: activityId)
    }

    func incrementView(activityId: String) async throws -> IncrementOutdoorSocialActivityViewResponse {
        let response = try await repository.incrementOutdoorSocialActivityView(activityId: activityId)
        await query.overlayView(activityId: activityId, view: response.view)
        await exploreQuery.overlayView(activityId: activityId, view: response.view)
        return response
    }

    func create(_ body: CreateOutdoorSocialActivityRequest) async throws -> CreateOutdoorSocialActivityResponse {
        let response = try await repository.createOutdoorSocialActivity(body)
        eventBus.invalidate()
        return response
    }

    func join(activityId: String, _ body: JoinOutdoorSocialActivityRequest = JoinOutdoorSocialActivityRequest()) async throws -> JoinOutdoorSocialActivityResponse {
        let response = try await repository.joinOutdoorSocialActivity(activityId: activityId, body)
        eventBus.invalidate()
        return response
    }

    func getMyRegistrationPayment(activityId: String) async throws -> PaymentHoldActivity {
        try await repository.getMyRegistrationPayment(activityId: activityId)
    }

    func payMyRegistrationPayment(activityId: String, paymentMethodId: String) async throws -> PaymentAttempt {
        let attempt = try await repository.payMyRegistrationPayment(activityId: activityId, PayPaymentRequest(paymentMethodId: paymentMethodId))
        invalidate()
        return attempt
    }

    /** Stripe 付款成功后 webhook 才改报名状态，让订阅方重拉。 */
    func invalidate() {
        eventBus.invalidate()
    }

    func exit(activityId: String) async throws -> OutdoorSocialRegistration {
        let registration = try await repository.exitOutdoorSocialActivity(activityId: activityId)
        eventBus.invalidate()
        return registration
    }

    func end(activityId: String) async throws {
        try await repository.endOutdoorSocialActivity(activityId: activityId)
        eventBus.invalidate()
    }

    func patchBasic(activityId: String, _ body: PatchOutdoorSocialActivityBasicRequest) async throws {
        try await repository.patchOutdoorSocialActivityBasic(activityId: activityId, body)
        eventBus.invalidate()
    }

    func markPaymentItemPaid(itemId: String) async throws {
        try await repository.markPaymentChecklistItemPaid(itemId: itemId)
        eventBus.invalidate()
    }

    func markPaymentItemUnpaid(itemId: String) async throws {
        try await repository.markPaymentChecklistItemUnpaid(itemId: itemId)
        eventBus.invalidate()
    }

    func settleAll(activityId: String) async throws -> OutdoorSocialPaymentChecklistResponse {
        let response = try await repository.settleAllPaymentChecklist(activityId: activityId)
        eventBus.invalidate()
        return response
    }

    func remindItems(activityId: String, itemIds: [String]) async throws {
        try await repository.remindPaymentChecklistItems(activityId: activityId, itemIds: itemIds)
        eventBus.invalidate()
    }
}

extension HostedChecklistRowUi {
    init(_ item: OutdoorSocialHostedPaymentChecklistItem) {
        self.init(
            checklistId: item.id,
            activityId: item.outdoorSocialActivityId,
            title: item.title.isEmpty ? String(item.outdoorSocialActivityId.prefix(8)) : item.title,
            venueName: item.venueName ?? item.address,
            startsAt: item.startsAt,
            isAllSettled: item.isAllSettled
        )
    }
}

extension MyChecklistItemRowUi {
    init(_ item: OutdoorSocialMyPaymentChecklistItem) {
        self.init(
            itemId: item.id,
            activityId: item.outdoorSocialActivityId,
            title: item.title.isEmpty ? String(item.outdoorSocialActivityId.prefix(8)) : item.title,
            venueName: item.venueName ?? item.address,
            startsAt: item.startsAt,
            paid: item.paid,
            priceAmount: item.priceAmount,
            currency: item.currency
        )
    }
}
